export type ResourceType = 'MATERIAL' | 'SERVICE';

export interface Resource {
  id: number;
  parent_resource_id: number | null;
  type: ResourceType;
  // Generated by the backend (MAT0001, SER0001), never changed.
  code: string;
  // Optional free text - e.g. the supplier's article number.
  reference: string | null;
  name: string;
  unit: string;
  selling_price: number;
  purchase_price: number | null;
  is_active: boolean;
}
